import React, {useEffect, useState} from 'react';

interface MatrixInputProps {
    n: number;
    matrix: number[][];
    vector: number[];
    onChange: (matrix: number[][], vector: number[]) => void;
}

const SmartInput: React.FC<{
    initialValue: number;
    onSave: (val: number) => void;
    placeholder?: string;
    className?: string;
}> = ({ initialValue, onSave, placeholder, className }) => {
    // Храним в локальном стейте строку, чтобы точка или минус не пропадали
    const [localValue, setLocalValue] = useState<string>(initialValue.toString());

    // Синхронизируем, если внешние данные изменились (например, при загрузке файла)
    useEffect(() => {
        setLocalValue(initialValue.toString());
    }, [initialValue]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value.replace(',', '.');
        // Разрешаем вводить всё, что похоже на начало числа
        if (val === '' || val === '-' || val === '.' || val === '-.' || !isNaN(Number(val))) {
            setLocalValue(val);
        }
    };

    const handleBlur = () => {
        // Когда уводим фокус — сохраняем результат в главный стейт
        const parsed = parseFloat(localValue);
        onSave(isNaN(parsed) ? 0 : parsed);
    };

    return (
        <input
            type="text"
            value={localValue === '0' && localValue !== '0.' ? '' : localValue}
            onChange={handleChange}
            onBlur={handleBlur}
            placeholder={placeholder}
            className={className}
        />
    );
};

export const MatrixInput: React.FC<MatrixInputProps> = ({
                                                            n, matrix, vector, onChange
                                                        }) => {
    const handleMatrixChange = (i: number, j: number, value: string) => {
        // 1. Заменяем запятую на точку для поддержки обоих раскладок
        const normalizedValue = value.replace(',', '.');

        // 2. Разрешаем промежуточные состояния: пустая строка, только минус,
        //    число с точкой на конце (например, "0.") или "-0."
        if (normalizedValue === '' || normalizedValue === '-' || normalizedValue.endsWith('.')) {
            // Чтобы React не "съел" точку или минус, мы временно обновляем матрицу
            // преобразуя это в число 0 для расчетов, но передаем строковое значение если нужно.
            // Но самый простой способ — хранить в стейте числа, а парсить аккуратно:
            const newMatrix = matrix.map(row => [...row]);
            newMatrix[i][j] = parseFloat(normalizedValue) || 0;
            onChange(newMatrix, vector);
            return;
        }

        // 3. Если это нормальное число — парсим
        const val = parseFloat(normalizedValue);
        if (!isNaN(val)) {
            const newMatrix = matrix.map(row => [...row]);
            newMatrix[i][j] = val;
            onChange(newMatrix, vector);
        }
    };

    const handleVectorChange = (i: number, value: string) => {
        const normalizedValue = value.replace(',', '.');

        if (normalizedValue === '' || normalizedValue === '-' || normalizedValue.endsWith('.')) {
            const newVector = [...vector];
            newVector[i] = parseFloat(normalizedValue) || 0;
            onChange(matrix, newVector);
            return;
        }

        const val = parseFloat(normalizedValue);
        if (!isNaN(val)) {
            const newVector = [...vector];
            newVector[i] = val;
            onChange(matrix, newVector);
        }
    };

    const getDisplayValue = (value: number): string => {
        return value.toString();
    };


    const getColumnWidth = () => {
        if (n <= 5) return 'min-w-[100px]';
        if (n <= 8) return 'min-w-[80px]';
        return 'min-w-[60px]';
    };

    const columnWidth = getColumnWidth();

    return (
        <div className="space-y-6 overflow-x-auto">
            <div>
                <label className="block text-sm font-medium text-gray-700 mb-3">
                    Матрица коэффициентов A:
                </label>
                <div className="inline-block min-w-full align-middle">
                    <div className="overflow-hidden border border-gray-200 rounded-lg">
                        <table className="min-w-full divide-y divide-gray-200">
                            <thead className="bg-gray-50">
                            <tr>
                                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-12">
                                    №
                                </th>
                                {Array.from({ length: n }).map((_, j) => (
                                    <th
                                        key={j}
                                        className={`px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider ${columnWidth}`}
                                    >
                                        a<sub>{j+1}</sub>
                                    </th>
                                ))}
                                <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider min-w-[100px]">
                                    b
                                </th>
                            </tr>
                            </thead>
                            <tbody className="bg-white divide-y divide-gray-200">
                            {Array.from({ length: n }).map((_, i) => (
                                <tr key={i} className="hover:bg-gray-50">
                                    <td className="px-4 py-2 whitespace-nowrap text-sm font-medium text-gray-900">
                                        {i + 1}
                                    </td>
                                    {Array.from({ length: n }).map((_, j) => (
                                        <td key={j} className="px-2 py-2">
                                            <SmartInput
                                                initialValue={matrix[i][j]}
                                                onSave={(val) => handleMatrixChange(i, j, val.toString())} // передаем как строку для твоей функции
                                                className="w-full px-2 py-1 text-center border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                                                placeholder={`a${i+1}${j+1}`}
                                            />
                                        </td>
                                    ))}
                                    <td className="px-2 py-2">
                                        <input
                                            type="text"
                                            value={getDisplayValue(vector[i] ?? 0)}
                                            onChange={(e) => handleVectorChange(i, e.target.value)}
                                            className="w-full px-2 py-1 text-center border border-blue-300 bg-blue-50 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                            step="any"
                                            placeholder={`b${i+1}`}
                                        />
                                    </td>
                                </tr>
                            ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-4 text-xs text-gray-500">
                <div className="flex items-center gap-2">
                    <div className="w-4 h-4 bg-gray-100 border border-gray-300 rounded"></div>
                    <span>Элементы матрицы A</span>
                </div>
                <div className="flex items-center gap-2">
                    <div className="w-4 h-4 bg-blue-50 border border-blue-300 rounded"></div>
                    <span>Правая часть b</span>
                </div>
            </div>
        </div>
    );
};
